import{_ as t,o as r,c as s,a2 as a}from"./chunks/framework.ChTAMbUy.js";const g=JSON.parse('{"title":"MCP Servers","description":"","frontmatter":{},"headers":[],"relativePath":"development/agentops/mcp_servers.md","filePath":"versions/development/agentops/mcp_servers.md","lastUpdated":1791569256000}'),o={name:"development/agentops/mcp_servers.md"};function i(n,e,l,c,p,d){return r(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="mcp-servers" tabindex="-1">MCP Servers <a class="header-anchor" href="#mcp-servers" aria-label="Permalink to &quot;MCP Servers&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Upstream documentation</p><p>For MCP and ToolHive concepts that are not specific to prokube, use the upstream documentation:</p><ul><li><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol documentation</a></li><li><a href="https://docs.stacklok.com/toolhive/" target="_blank" rel="noreferrer">ToolHive documentation</a></li><li><a href="https://docs.stacklok.com/toolhive/reference/crds/" target="_blank" rel="noreferrer">ToolHive Kubernetes CRD reference</a></li></ul></div><p>MCP servers expose tools, data sources, and internal APIs to AI assistants through the Model Context Protocol. In prokube, MCP servers run as Kubernetes workloads managed by ToolHive instead of local processes on a developer machine.</p><p>Use an MCP server when an agent or MCP-capable client needs a tool such as browser automation, a database, or an internal API. The server runs in your workspace with its own configuration and credentials, so the agent does not need broad user credentials to reach the service.</p><h2 id="how-prokube-runs-mcp-servers" tabindex="-1">How prokube Runs MCP Servers <a class="header-anchor" href="#how-prokube-runs-mcp-servers" aria-label="Permalink to &quot;How prokube Runs MCP Servers&quot;">​</a></h2><p>Open <strong>MCP</strong> from the prokube UI sidebar under <strong>AgentOps</strong>. Select the workspace before deploying or inspecting servers.</p><p>An MCP server is deployed into the selected workspace namespace as a <a href="https://docs.stacklok.com/toolhive/reference/crds/" target="_blank" rel="noreferrer">ToolHive <code>MCPServer</code></a> resource. ToolHive runs the server and its local MCP proxy. prokube adds:</p><ul><li>a UI for deploying servers from the catalog or from a custom image;</li><li>workspace authorization;</li><li>logs, events, and metrics for each server;</li><li>optional external access through Agent Gateway.</li></ul><p>Every deployed server can be reached in two ways. Agents and other workloads in the same workspace use one shared workspace endpoint without an API key. Clients outside the workspace call each server through Agent Gateway with an API key:</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/diagrams/agentops/mcp-servers-flow.svg" alt="Diagram: agents and other workloads in the workspace reach all MCP servers and memory stores through one workspace MCP endpoint without an API key. External MCP clients reach each server through Agent Gateway at /svc/mcp/workspace/server with an API key that has access to that server." loading="lazy"></p><p>The MCP page contains two main sections:</p><ul><li><strong>Deployed Servers</strong>: MCP servers currently running in the selected workspace.</li><li><strong>Server Catalog</strong>: ready-to-deploy MCP servers, each with its image and required configuration already described.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/mcp/landing-page-with-server-list-and-catalogue.png" alt="MCP Servers page with deployed servers and server catalog" loading="lazy"></p><h2 id="deploy-from-the-catalog" tabindex="-1">Deploy from the Catalog <a class="header-anchor" href="#deploy-from-the-catalog" aria-label="Permalink to &quot;Deploy from the Catalog&quot;">​</a></h2><p>Use the catalog for known server images and common integrations. Each catalog card describes the server and its tools, and shows compatibility badges such as <strong>Requires Root</strong>.</p><p>The catalog can be filtered by:</p><ul><li>search text;</li><li>tier: <strong>Official</strong> or <strong>Community</strong>;</li><li>source: <strong>prokube.ai Only</strong> or <strong>Third Party Only</strong>;</li><li>sort order: stars or name.</li></ul><p>Click a catalog card to deploy it. The deploy dialog shows:</p><ul><li><strong>Namespace</strong>: target workspace namespace.</li><li><strong>Server Name</strong>: Kubernetes resource name for the MCP server.</li><li><strong>Configuration</strong>: required and optional environment variables from the catalog entry.</li><li><strong>Registry Credentials</strong>: image pull secrets available in the workspace.</li><li><strong>Resource Limits</strong>: optional CPU and memory requests and limits.</li><li><strong>Technical Details</strong>: image, transport, and provided tools.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/mcp/playwright-launch-dialog.png" alt="Deploy dialog for a catalog MCP server" loading="lazy"></p><p>Environment variables can be entered directly or read from a Kubernetes Secret in the workspace. Use Secrets for tokens, passwords, API keys, and other sensitive values. See <a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a>.</p><h3 id="catalog-source-and-trust" tabindex="-1">Catalog Source and Trust <a class="header-anchor" href="#catalog-source-and-trust" aria-label="Permalink to &quot;Catalog Source and Trust&quot;">​</a></h3><p>The catalog comes from the upstream <a href="https://github.com/stacklok/toolhive-catalog" target="_blank" rel="noreferrer">ToolHive Catalog</a>, a community-maintained list of MCP servers. Each entry is reviewed through the ToolHive project and lists its publisher, source repository, tools, and required configuration. That makes it a safer starting point than an arbitrary container image.</p><p>A catalog entry is still not an approval for your environment. The tier tells you who maintains it:</p><ul><li><strong>Official</strong> entries are maintained by the MCP team, the upstream project, or platform owners.</li><li><strong>Community</strong> entries are contributed and maintained by the community.</li><li><strong>prokube.ai Only</strong> narrows the list to entries published or curated by prokube.ai where available.</li></ul><p>Before giving an MCP server credentials or access to internal systems, review what it connects to, who maintains it, which tools it exposes, and whether it needs broad permissions. Prefer Official or internally maintained servers for production workflows.</p><h2 id="deploy-a-custom-server" tabindex="-1">Deploy a Custom Server <a class="header-anchor" href="#deploy-a-custom-server" aria-label="Permalink to &quot;Deploy a Custom Server&quot;">​</a></h2><p>Use <strong>Deploy Custom Server</strong> when the server is not in the catalog or when you maintain your own image.</p><p>Required fields:</p><ul><li><strong>Server Name</strong>: Kubernetes-compatible resource name.</li><li><strong>Container Image</strong>: image that runs the MCP server.</li><li><strong>Transport Protocol</strong>: <code>stdio</code>, <code>sse</code>, or <code>streamable-http</code>.</li><li><strong>Proxy Port</strong>: port exposed by the ToolHive proxy.</li></ul><p>Optional fields:</p><ul><li>environment variables, either direct values or Secret references;</li><li>image pull credentials for private registries;</li><li>CPU and memory requests and limits;</li><li>container arguments;</li><li>root or writable-filesystem options for images that require them;</li><li>persistent storage for servers that need data to survive pod restarts;</li><li>live view for browser-based servers such as noVNC-backed Playwright images.</li></ul><p>Prefer custom images that run as non-root and work with a read-only root filesystem. Images that require root or write access are harder to run in restricted workspaces and have a larger security footprint.</p><h2 id="use-yaml-for-advanced-configuration" tabindex="-1">Use YAML for Advanced Configuration <a class="header-anchor" href="#use-yaml-for-advanced-configuration" aria-label="Permalink to &quot;Use YAML for Advanced Configuration&quot;">​</a></h2><p>Use YAML when the form does not expose a setting you need. The deploy dialog can generate a ToolHive <code>MCPServer</code> manifest from the form fields. Inspect or adjust it, then submit it through the UI.</p><p>The namespace is set by prokube to the selected workspace namespace. Custom YAML must still be a ToolHive <code>MCPServer</code> resource using a supported <code>toolhive.stacklok.dev</code> API version.</p><h2 id="connect-clients" tabindex="-1">Connect Clients <a class="header-anchor" href="#connect-clients" aria-label="Permalink to &quot;Connect Clients&quot;">​</a></h2><p>The <strong>Deployed Servers</strong> table shows each server&#39;s status and, when available, its URL. Open a server to see its connection details on the <strong>Overview</strong> tab.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/mcp/playwright-overview.png" alt="MCP server overview with external and internal connection details" loading="lazy"></p><h3 id="from-the-workspace" tabindex="-1">From the Workspace <a class="header-anchor" href="#from-the-workspace" aria-label="Permalink to &quot;From the Workspace&quot;">​</a></h3><p>One internal endpoint serves the tools of all deployed MCP servers and <a href="./memory_stores.html">Memory Stores</a> in the workspace. New servers join it automatically. It accepts calls only from the same workspace and needs no API key.</p><ul><li><strong>kagent agents</strong>: open <strong>Agents</strong> and select the MCP tools when creating or editing the agent. The tools appear under the managed <code>gateway-mcp</code> endpoint, with no further setup. Add an entry under <strong>Tools</strong> only to connect an MCP endpoint outside the workspace.</li><li><strong>Other workloads</strong>: use the internal URL shown on the <strong>Overview</strong> tab.</li></ul><h3 id="from-outside-the-workspace" tabindex="-1">From Outside the Workspace <a class="header-anchor" href="#from-outside-the-workspace" aria-label="Permalink to &quot;From Outside the Workspace&quot;">​</a></h3><p>External clients use the server&#39;s external URL, <code>https://&lt;your-prokube-domain&gt;/svc/mcp/&lt;workspace&gt;/&lt;server&gt;</code>, with an <a href="./../platform/api_keys.html">API key</a> that has access to that server. The <strong>Overview</strong> tab shows a ready-to-copy client configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;&lt;server&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://&lt;your-prokube-domain&gt;/svc/mcp/&lt;workspace&gt;/&lt;server&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer &lt;api-key&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If the key was created with the <code>x-api-key</code> format, send <code>x-api-key: &lt;api-key&gt;</code> instead of the <code>Authorization</code> header.</p><p>In OpenCode Labs, add the server&#39;s URL from the <strong>Overview</strong> tab through the OpenCode MCP manager and set any required headers or OAuth settings there. See <a href="./../labs/opencode.html#add-mcp-servers">OpenCode: Add MCP Servers</a>.</p><h2 id="browser-automation-servers" tabindex="-1">Browser Automation Servers <a class="header-anchor" href="#browser-automation-servers" aria-label="Permalink to &quot;Browser Automation Servers&quot;">​</a></h2><p>Some catalog entries, such as the prokube Playwright noVNC image, include live browser viewing and trace support.</p><p>For these servers, the details page can show:</p><ul><li><strong>Live View</strong> for an interactive browser session;</li><li><strong>Traces</strong> for recorded Playwright sessions;</li><li><strong>Logs</strong> and <strong>Events</strong> for debugging startup and runtime issues;</li><li><strong>Metrics</strong> for runtime monitoring.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/mcp/playwright-live-browser-viewer.png" alt="Live browser view for a browser automation MCP server" loading="lazy"></p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/mcp/playwright-details-metrics.png" alt="MCP server metrics for a browser automation server" loading="lazy"></p><p>Live view is only available for servers that declare live-view support in the catalog or custom configuration.</p><h2 id="security-and-operations" tabindex="-1">Security and Operations <a class="header-anchor" href="#security-and-operations" aria-label="Permalink to &quot;Security and Operations&quot;">​</a></h2><ul><li>Deploy servers only in workspaces where the intended users should have access to the exposed tools.</li><li>Store sensitive configuration in <a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a> instead of direct environment variable values.</li><li>Prefer <strong>Official</strong> or internally maintained catalog entries for production use.</li><li>Review third-party images before granting access to internal data or network destinations.</li><li>Avoid root and writable-root-filesystem options unless the image requires them.</li><li>Restricted workspace security policies can reject servers that request root privileges.</li><li>Set resource requests and limits for long-running or shared servers.</li><li>Delete MCP servers that are no longer used.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Most checks start on the server&#39;s details page: <strong>Events</strong> show scheduling and image pull problems, and <strong>Logs</strong> show startup and tool call errors.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/mcp/playwright-details-logs.png" alt="Logs tab on the MCP server details page" loading="lazy"></p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Server stays <code>Pending</code></td><td>Open the details page and check <strong>Events</strong> and <strong>Logs</strong>. Also verify image pull credentials and workspace quota.</td></tr><tr><td>Image cannot be pulled</td><td>Confirm the image name and select the required registry credential for private registries. See <a href="./../platform/kubernetes.html#registry-credentials">Registry Credentials</a>.</td></tr><tr><td>Deployment is rejected by security policy</td><td>The image may require root or a writable filesystem in a restricted workspace. Use a compliant image or ask an administrator to review the workspace policy.</td></tr><tr><td>Required configuration is missing</td><td>Check the catalog entry&#39;s required environment variables and provide direct values or Secret references.</td></tr><tr><td>Client cannot connect</td><td>Confirm the server is <code>Running</code>, copy the current URL, and verify the API key is scoped to the MCP server.</td></tr><tr><td>Tool calls fail after connecting</td><td>Check server logs, required upstream credentials, workspace network policy, and whether the tool depends on an external service.</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../platform/kubernetes.html">Kubernetes Resources</a></li><li><a href="./agents.html">Agents</a></li></ul>`,62)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
